<?php require_once '../functions.php'; require_admin(); $title='CRUD Produk';$edit=(int)($_GET['edit']??0);$error='';$row=null;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'save';if($action==='delete'){$id=(int)$_POST['id'];$s=$koneksi->prepare('DELETE FROM produk WHERE id_produk=?');$s->bind_param('i',$id);if($s->execute())flash('success','Produk dihapus.');else flash('error','Produk tidak dapat dihapus karena sudah dipakai pada transaksi.');redirect('produk.php');}$id=(int)($_POST['id']??0);$name=trim($_POST['nama_produk']??'');$harga=max(0,(float)($_POST['harga']??0));$stok=max(0,(int)($_POST['stok']??0));$cat=(int)($_POST['id_kategori']??0);$desc=trim($_POST['deskripsi']??'');$image=trim($_POST['image_url']??'');if($name==='')$error='Nama produk wajib diisi.';else if($id){$s=$koneksi->prepare('UPDATE produk SET nama_produk=?,harga=?,stok=?,id_kategori=?,deskripsi=?,image_url=? WHERE id_produk=?');$s->bind_param('sdiissi',$name,$harga,$stok,$cat,$desc,$image,$id);$s->execute();flash('success','Produk berhasil diperbarui.');redirect('produk.php');}else{$s=$koneksi->prepare('INSERT INTO produk(nama_produk,harga,stok,id_kategori,deskripsi,image_url) VALUES(?,?,?,?,?,?)');$s->bind_param('sdiiss',$name,$harga,$stok,$cat,$desc,$image);$s->execute();flash('success','Produk berhasil ditambahkan.');redirect('produk.php');}}
if($edit){$s=$koneksi->prepare('SELECT * FROM produk WHERE id_produk=?');$s->bind_param('i',$edit);$s->execute();$row=$s->get_result()->fetch_assoc();}$cats=$koneksi->query('SELECT * FROM kategori ORDER BY nama_kategori');$list=$koneksi->query('SELECT p.*,k.nama_kategori FROM produk p LEFT JOIN kategori k ON k.id_kategori=p.id_kategori ORDER BY p.id_produk DESC');include 'header.php'; ?>
<div class="container"><div class="section-head"><div><h1>CRUD Produk</h1><p class="muted">Tambah, edit, dan hapus katalog produk.</p></div><a class="btn outline" href="produk.php">+ Produk Baru</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="panel"><h2><?=$row?'Edit Produk':'Tambah Produk'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$row['id_produk']??0?>"><input type="hidden" name="action" value="save"><div class="form-grid"><div><label>Nama Produk</label><input name="nama_produk" value="<?=e($row['nama_produk']??'')?>" required></div><div><label>Harga</label><input type="number" name="harga" min="0" step="0.01" value="<?=e($row['harga']??0)?>" required></div><div><label>Stok</label><input type="number" name="stok" min="0" value="<?=e($row['stok']??0)?>" required></div><div><label>Kategori</label><select name="id_kategori"><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id_kategori']?>" <?=($row['id_kategori']??0)==$c['id_kategori']?'selected':''?>><?=e($c['nama_kategori'])?></option><?php endwhile;?></select></div></div><label>URL Gambar (opsional)</label><input name="image_url" value="<?=e($row['image_url']??'')?>" placeholder="https://..."><label>Deskripsi</label><textarea name="deskripsi"><?=e($row['deskripsi']??'')?></textarea><button class="btn"><?=$row?'Simpan Perubahan':'Tambah Produk'?></button><?php if($row):?><a class="btn outline" href="produk.php">Batal</a><?php endif;?></form></div><div class="table-wrap"><table><tr><th>ID</th><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Aksi</th></tr><?php while($p=$list->fetch_assoc()):?><tr><td><?=$p['id_produk']?></td><td><?=e($p['nama_produk'])?></td><td><?=e($p['nama_kategori']??'-')?></td><td><?=rupiah($p['harga'])?></td><td><?=$p['stok']?></td><td><a href="?edit=<?=$p['id_produk']?>">Edit</a><form method="post" class="inline" onsubmit="return confirm('Hapus produk ini?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id_produk']?>"><button class="link-danger">Hapus</button></form></td></tr><?php endwhile;?></table></div></div><?php include '../footer.php'; ?>
